const coordinates = $input.first().json.coordinates;

/**
 * Calculates the Euclidian distance between two coordinates.
 * @returns {number}
 */
function euclidianDistance(one, two) {
  return Math.sqrt(
    (one.x - two.x) ** 2 +
    (one.y - two.y) ** 2 +
    (one.z - two.z) ** 2
  )
}

/**
 * Returns an array of distances, where each distance is an array itself, like
 * `[distance, fromIndex, toIndex]`, indices pointing to coordinates in the
 * global coordinates array.
 *
 * @return {Array<Array<number>>}
 */
function findDistances() {
  const distances = [];
  const length = coordinates.length;
  for (let i = 0; i < length - 1; i++) {
    const one = coordinates[i];
    for (let j = i + 1; j < length; j++) {
      const two = coordinates[j];
      distances.push([euclidianDistance(one, two), i, j])
    }
  }

  return distances.sort((a,b) => a[0] - b[0]);
}
const distances = findDistances();

/**
 * Create circuits between coordinates based on distances.
 * @param distances
 * @returns {*[][]}
 */
function createCircuits(distances) {
  let circuits = [[distances[0][1], distances[0][2]]];

  for (let i = 1; i < distances.length; i++) {
    const start = distances[i][1];
    const end = distances[i][2];
    const notConnected = [];
    const connected = [[start, end]];

    for (const circuit of circuits) {
      if (circuit.includes(start) || circuit.includes(end)) {
        connected.push(circuit);
      } else {
        notConnected.push(circuit);
      }
    }

    // Append the new circuit by prepending start and end to the merged connected circuits
    const newCircuit = Array.from(new Set([start, end, ...connected.flat()]));
    notConnected.push(newCircuit);
    circuits = notConnected;
  }
  return circuits;
}

// Take top 1000 distances to create circuits for as per the instructions
const firstDistances = distances.slice(0, 1000);
const circuits = createCircuits(firstDistances)
  .map(circuit => circuit.length)
  .sort((a,b) => b - a); // Sort circuits by number of coordinates included, descending

// Multiply sizes of the three largest circuits
const result = circuits[0] * circuits[1] * circuits[2];

return [{ result }];

