            }
        }

        const newCircuit = Array.from(new Set([start, end, ...connected.flat()]));
        notConnected.push(newCircuit);
        circuits = notConnected;

        // Single circuit with all 1000 points found
        if (circuits.length === 1 && circuits[0].length === 1000) {
            return [start, end];
        }
    }
    return [-1, -1];
}

